// Bu akış yalnızca sinyal üretir; borsada otomatik emir açmaz.
const API = 'https://kripto-sinyal.erenkaraca2005.workers.dev';
const KEY = 'BURAYA_API_ANAHTARI';
const SYMBOLS = ['BTCUSDT', 'ETHUSDT', 'BNBUSDT', 'SOLUSDT', 'XRPUSDT'];
const INTERVAL = '1h';
const LIMIT = 250;
const RISK_ATR = 1.5;
const REWARD_ATR = 2.25;
const h = this.helpers;

function ema(values, period) {
  const k = 2 / (period + 1);
  const output = [values[0]];
  for (let i = 1; i < values.length; i++) output.push(values[i] * k + output[i - 1] * (1 - k));
  return output;
}
function rsi(values, period = 14) {
  let gain = 0, loss = 0;
  for (let i = 1; i <= period; i++) { const d = values[i] - values[i - 1]; if (d >= 0) gain += d; else loss -= d; }
  gain /= period; loss /= period;
  for (let i = period + 1; i < values.length; i++) { const d = values[i] - values[i - 1]; gain = (gain * (period - 1) + Math.max(d, 0)) / period; loss = (loss * (period - 1) + Math.max(-d, 0)) / period; }
  return loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
}
function atr(candles, period = 14) {
  const ranges = [];
  for (let i = 1; i < candles.length; i++) { const c = candles[i], p = candles[i - 1]; ranges.push(Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close))); }
  return ranges.slice(-period).reduce((a, b) => a + b, 0) / period;
}
function round(value) { return Number(value.toPrecision(8)); }

const existing = await h.httpRequest({ url: API + '/api/signals', json: true });
const results = [];
for (const symbol of SYMBOLS) {
  const raw = await h.httpRequest({ url: `https://api.binance.com/api/v3/klines?symbol=${symbol}&interval=${INTERVAL}&limit=${LIMIT}`, json: true });
  const candles = raw.map(x => ({ close: +x[4], high: +x[2], low: +x[3] }));
  if (candles.length < 60) continue;
  const closes = candles.map(x => x.close);
  const price = closes.at(-1);
  const e20 = ema(closes, 20).at(-1);
  const e50 = ema(closes, 50).at(-1);
  const e12 = ema(closes, 12);
  const e26 = ema(closes, 26);
  const macdSeries = e12.map((value, index) => value - e26[index]);
  const macd = macdSeries.at(-1);
  const macdSignal = ema(macdSeries, 9).at(-1);
  const r = rsi(closes);
  const a = atr(candles);
  if (!Number.isFinite(a) || a <= 0) continue;

  const buy = price > e20 && e20 > e50 && r >= 52 && r <= 68 && macd > macdSignal;
  const sell = price < e20 && e20 < e50 && r >= 32 && r <= 48 && macd < macdSignal;
  if (!buy && !sell) continue;
  if (existing.some(signal => signal.symbol === symbol && signal.status === 'open')) continue;

  const side = buy ? 'BUY' : 'SELL';
  const entry = price;
  const sl = buy ? price - RISK_ATR * a : price + RISK_ATR * a;
  const tp = buy ? price + REWARD_ATR * a : price - REWARD_ATR * a;
  const payload = { symbol, side, entry: round(entry), tp: round(tp), sl: round(sl), tf: INTERVAL };
  const saved = await h.httpRequest({ method: 'POST', url: API + '/api/signals', headers: { Authorization: 'Bearer ' + KEY }, body: payload, json: true });
  results.push({ json: { ...saved, indicators: { rsi: round(r), ema20: round(e20), ema50: round(e50), macd: round(macd), atr: round(a) } } });
}
return results;
